Câu 3: (0.5 điểm) Cho một chương trình như sau:
#include <iostream>
using namespace std;
int main()
{
    int a = 12, b = 7;
    int *pa = &a, *pb = &b;
    cout << "&a=" << &a << endl;
    cout << "&pa=" << &pa << endl;
    cout << "&b=" << &b << endl;
    cout << "&pb=" << &pb << endl;
    *pb = a % 5;
    pa = pb;
    *pa = *pb + a;
    cout << &(*pa) << " ";
    cout << *(&a) << " ";
    cout << pb - pa << " ";
    cout << (*pb) + (*pa) << " ";
    return 0;
}
Bốn dòng đầu tiên được in ra màn hình là:
&a=0x6ffdf0
&pa=0x6ffde8
&b=0x6ffdec
&pb=0x6ffde0
